package io.github.wlroots.budsapp.model

import android.content.Context
import android.util.Log
import org.json.JSONArray
import org.json.JSONObject

/**
 * Loads the per-model capability table generated by tools/convert-configs.mjs.
 */
object DeviceCatalog {
    private const val TAG = "DeviceCatalog"
    private const val ASSET = "models.json"

    @Volatile
    private var models: List<DeviceConfig> = emptyList()

    @Volatile
    private var loaded = false

    fun all(context: Context): List<DeviceConfig> {
        ensureLoaded(context)
        return models
    }

    fun byModelId(context: Context, modelId: String): DeviceConfig? {
        ensureLoaded(context)
        val normalized = modelId.trim().uppercase()
        return models.firstOrNull { it.modelId.equals(normalized, ignoreCase = true) }
    }

    fun byName(context: Context, deviceName: String): DeviceConfig? {
        ensureLoaded(context)
        return models.firstOrNull { it.matches(deviceName) }
    }

    /**
     * Used when the model id is unknown and no name pattern matches, so the app still
     * exposes the common Nothing/CMF feature set instead of refusing to work.
     */
    fun generic(deviceName: String): DeviceConfig = DeviceConfig(
        modelId = "",
        name = deviceName.ifBlank { "Nothing / CMF" },
        patternSource = null,
        patternFlags = "",
        batteryLR = true,
        batteryCase = true,
        batterySingle = false,
        eqPresets = linkedMapOf(
            "balanced" to 0x00,
            "voice" to 0x01,
            "more_treble" to 0x02,
            "more_bass" to 0x03,
            "custom" to 0x05,
        ),
        eqListeningModeType = false,
        personalizeAnc = false,
        noise = NoiseConfig(
            offByte = 0x05,
            transparencyByte = 0x07,
            noiseCancellationByte = null,
            levels = linkedMapOf("low" to 0x03, "mid" to 0x02, "high" to 0x01, "adaptive" to 0x04),
        ),
        bassEnhanceLevel = 0,
        inEarDetection = true,
        lowLatencyMode = true,
        fitTest = false,
        ring = true,
        ringLegacy = false,
        dualConnection = false,
        dualConnectionReboot = false,
        spatialAudioSwitch = false,
        spatialHeadTracking = false,
        spatialImmersiveModes = false,
        autoPowerOff = emptyList(),
        noUtcTimeUpdate = false,
        gestures = null,
        icon = "earbuds-stem",
    )

    @Synchronized
    private fun ensureLoaded(context: Context) {
        if (loaded) return
        loaded = true
        try {
            val text = context.assets.open(ASSET).bufferedReader().use { it.readText() }
            val root = JSONObject(text)
            val array = root.optJSONArray("models") ?: JSONArray()
            models = buildList {
                for (index in 0 until array.length()) {
                    val obj = array.optJSONObject(index) ?: continue
                    runCatching { parse(obj) }
                        .onSuccess { add(it) }
                        .onFailure { Log.w(TAG, "Failed to parse model at $index", it) }
                }
            }
            Log.i(TAG, "Loaded ${models.size} device configs")
        } catch (e: Exception) {
            Log.e(TAG, "Unable to load $ASSET", e)
            models = emptyList()
        }
    }

    private fun parse(obj: JSONObject): DeviceConfig {
        val pattern = obj.optJSONObject("pattern")
        val eq = linkedMapOf<String, Int>()
        obj.optJSONObject("eqPreset")?.let { preset ->
            for (key in preset.keys()) {
                eq[key] = preset.optInt(key)
            }
        }

        return DeviceConfig(
            modelId = obj.optString("modelId"),
            name = obj.optString("name"),
            patternSource = pattern?.optString("source"),
            patternFlags = pattern?.optString("flags") ?: "",
            batteryLR = obj.optBoolean("batteryLR", false),
            batteryCase = obj.optBoolean("batteryCase", false),
            batterySingle = obj.optBoolean("batterySingle", false),
            eqPresets = eq,
            eqListeningModeType = obj.optBoolean("eqListeningModeType", false),
            personalizeAnc = obj.optBoolean("personalizeAnc", false),
            noise = parseNoise(obj.optJSONObject("noiseControl")),
            bassEnhanceLevel = obj.optInt("bassEnhanceLevel", 0),
            inEarDetection = obj.optBoolean("inEarDetection", false),
            lowLatencyMode = obj.optBoolean("lowLatencyMode", false),
            fitTest = obj.optBoolean("fitTest", false),
            ring = obj.optBoolean("ring", false),
            ringLegacy = obj.optBoolean("ringLegacy", false),
            dualConnection = obj.optBoolean("dualConnection", false),
            dualConnectionReboot = obj.optBoolean("dualConnectionReboot", false),
            spatialAudioSwitch = obj.optBoolean("spatialAudioSwitch", false),
            spatialHeadTracking = obj.optBoolean("spatialHeadTracking", false),
            spatialImmersiveModes = obj.optBoolean("spatialimmersiveModes", false),
            autoPowerOff = obj.optJSONArray("autoPowerOff")?.toIntList() ?: emptyList(),
            noUtcTimeUpdate = obj.optBoolean("noUTCTimeUpdate", false),
            gestures = parseGestures(obj.optJSONObject("gestureOptions")),
            icon = obj.optString("budsIcon"),
        )
    }

    private fun parseNoise(obj: JSONObject?): NoiseConfig? {
        if (obj == null) return null
        val nc = obj.optJSONObject("noiseCancellation")
        val levels = linkedMapOf<String, Int>()
        nc?.optJSONObject("levels")?.let { levelObj ->
            for (key in levelObj.keys()) levels[key] = levelObj.optInt(key)
        }
        return NoiseConfig(
            offByte = obj.optJSONObject("off")?.optIntOrNull("byte"),
            transparencyByte = obj.optJSONObject("transparency")?.optIntOrNull("byte"),
            noiseCancellationByte = nc?.optIntOrNull("byte"),
            levels = levels,
        )
    }

    private fun parseGestures(obj: JSONObject?): GestureConfig? {
        if (obj == null) return null
        val slots = ArrayList<GestureSlotDef>()
        obj.optJSONArray("slots")?.let { array ->
            for (index in 0 until array.length()) {
                val slot = array.optJSONObject(index) ?: continue
                slots.add(
                    GestureSlotDef(
                        group = slot.optString("group"),
                        device = slot.optInt("device"),
                        buttonId = slot.optInt("buttonId"),
                        type = slot.optString("type"),
                    ),
                )
            }
        }

        val mapping = obj.optJSONObject("mapping")
        val gestureTypes = linkedMapOf<String, Int>()
        mapping?.optJSONObject("gestureTypes")?.let { types ->
            for (key in types.keys()) gestureTypes[key] = types.optInt(key)
        }
        val actions = linkedMapOf<String, List<Int>>()
        mapping?.optJSONObject("actions")?.let { actionObj ->
            for (key in actionObj.keys()) {
                actions[key] = actionObj.optJSONArray(key)?.toIntList() ?: emptyList()
            }
        }

        val gestures = linkedMapOf<String, GestureMapping>()
        obj.optJSONObject("gestures")?.let { gestureObj ->
            for (key in gestureObj.keys()) {
                val value = gestureObj.optJSONObject(key) ?: continue
                gestures[key] = GestureMapping(
                    type = value.optString("type"),
                    actions = value.optJSONArray("actions")?.toStringList() ?: emptyList(),
                )
            }
        }

        val modes = obj.optJSONArray("noiseControlModes")?.toStringList() ?: emptyList()

        return GestureConfig(
            defaultHex = if (obj.has("default")) obj.optString("default") else null,
            slots = slots,
            gestureTypes = gestureTypes,
            actions = actions,
            gestures = gestures,
            noiseControlModes = modes,
        )
    }

    private fun JSONArray.toIntList(): List<Int> = buildList {
        for (index in 0 until length()) add(optInt(index))
    }

    private fun JSONArray.toStringList(): List<String> = buildList {
        for (index in 0 until length()) add(optString(index))
    }

    private fun JSONObject.optIntOrNull(key: String): Int? =
        if (has(key) && !isNull(key)) optInt(key) else null
}
